export default [{"id":643,"question":"العربات التي في الصفا لها مكان خاص، فإذا انتهى المكان رجع ولم يبق في الصفا، هل يجزئه ذلك؟","title":"ما كيفية استيفاء السعي بين الصفا والمروة؟","answer":"الجواب: لا بدّ أن يستوفي ما بين الصفا والمروة ولو ينزل من العربة حتى يكمل، وإلا يصبر حتى يدخل العربة حتى يكمل ما بين الصفا والمروة، أساس هذه وأساس هذه.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6660/ما-كيفية-استيفاء-السعي-بين-الصفا-والمروة","audio":"https://files.zadapps.info/binbaz.org.sa/maram210 - 01 -  Start.mp3","categories":["السعي"]},{"id":644,"question":"حد الصفا وحد المروة..... المرتفع هو حدود الصفا والمروة؟ يعني الجبلان من أول ما يبتدئ ويصعد إلى الآخِر...  والمروة؟","title":"ما حدود الصفا والمروة؟","answer":"الجواب: أسفل الدرج، أسفل الدرجات، منتهى درج الصفا والمروة هذا ما بينهما.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6673/ما-حدود-الصفا-والمروة","audio":"https://files.zadapps.info/binbaz.org.sa/maram211 - 01 -  Start.mp3","categories":["السعي"]},{"id":651,"question":"المرأة إذا حاضت بعد الطواف ثم قلنا لها تسعى؛ لأنه لا يشترط لها الطهارة: ألا يُعتبر هذا مكثًا في المسجد؟","title":"ما حكم السعي للمرأة الحائض؟","answer":"الجواب: لا، ما يخالف، تسعى ولا بأس، تسعى وتتم عمرتها وحجتها؛ لأن السعي لا يشترط له الطهارة والمسعى لا يشترط ألا يطوف فيه إلا طاهر، المسعى مشروع للرجال والنساء السعي فيه، وليس له حكم المسجد من جهة منع الحائض.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6682/ما-حكم-السعي-للمراة-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/maram220 - 03 - .mp3","categories":["السعي"]},{"id":654,"question":"في الطواف نشاهد ناس معهم كتيبات بدعية دعاء الشوط الأول، أو الشوط الثاني، هل ينصحهم أو يشتغل بالأذكار ويدعو؟","title":"حكم تخصيص أشواط الطواف بأدعية معيّنة","answer":"الجواب: يشتغل بالأذكار ويدعو، وإن علّمهم فلا بأس، إن قال ما لها أذكار خاصة فالأمر واسع؛ لأن هؤلاء عامة يحتاجون إلى من يعلمهم، ما يعرفون شيئًا، ولكن ما هناك ذكر مخصص لكل شوط، إنما هذا يوجد في بعض المناسك تسهيلاً على الناس، ولكن يُعلَّمون: ترى ما في شيء خاص بالشوط الأول أو الثاني، الإنسان يذكر ويدعو الله في جميع الأشواط بما تيسر.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6685/حكم-تخصيص-اشواط-الطواف-بادعية-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/maram223 - 03 - .mp3","categories":["الطواف بالبيت","السعي","الأدعية والأذكار"]},{"id":1225,"question":"رجلٌ حجَّ أكثر من حجةٍ، ولم يسعَ سعي الحج؛ ظانًّا أن طواف الإفاضة يكفي عنه، وأن السعي لغير أهل مكة فقط وللابس الإحرام، وهو مصري مُقيم بمكة منذ سنين عديدة؟","title":"حكم من حج عدة حجات وترك السعي جهلًا","answer":"الجواب:\nهذا غلطٌ كبيرٌ، لا بد من السعي، وإن كان هناك قولٌ آخر أن السعي سنة، وقول آخر أنه واجب يُجبر بدمٍ، لكن الصحيح أنه ركنٌ من أركان الحج، فعليه أن يسعى بعدد الحجَّات التي ترك فيها السعي، بالنية، ويكفي والحمد لله، عليه أن يسعى بعدد الحجَّات: ثلاث مراتٍ إن كان حجَّ ثلاثًا، وإن كان أربعًا فأربع مرات، وهكذا، بالنية عن الأولى والثانية والثالثة والحمد لله، وعليه التوبة والاستغفار، وإن كانت عنده زوجة قد وطئها فعليه ذبيحة، عن كل حجةٍ ذبيحة، عن كونه وطأ قبل أن يسعى، إذا قدر، فإن عجز يصوم عشرة أيام عن كل ذبيحةٍ.","link":"https://binbaz.org.sa/fatwas/21287/حكم-من-حج-عدة-حجات-وترك-السعي-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1030رجل حج أكثر من حجة ولم يسعى سعي الحج ظاناً أن طواف الإفاضة كيفي عنه؟ ابن باز.mp3","categories":["السعي"]},{"id":3419,"question":"حاجّ ترك السعي جهلًا منه، وقد مضى ست سنوات، وتزوج في هذه المدة، ماذا عليه يا شيخ؟","title":"حكم مَنْ حج وترك السعي جهلاً منه منذ زمن","answer":"الجوب: حج، أو عمرة؟\nالطالب: لا، حج.\nالشيخ: ولا حج بعدها، ولا اعتمر، ولا شيء؟\nالطالب: مرة.\nالشيخ: الظاهر أنه يجدّد العقد، مازال مُحْرِما، عليه أن يرجع إلى مكة ويسعى، ويقصر، ويَحِلّ، ويجدّد النكاح، ولا عليه شيء، عليه أن يجدّد عقد النكاح، والحمد لله، وأولاده يُنسبون إليه.\nس: والمحظورات التي ارتكبها ما عليه شيء؟\nالشيخ: في عمرته؟\nالطالب: لا، في الحج.\nالشيخ: هو حج مفردًا، أو حج متمتعًا؟\nالطالب: لا، متمتع.\nالشيخ: ولا سعى؟\nالطالب: أي نعم...\nالشيخ: هذا في قول آخر لشيخ الإسلام ابن تيمية وجماعة يرون لا شيء عليه، ويكفيه السعي الأول، هذا على كل حال جاهل ما عليه  شيء من جهة لُبسه، وتقصيره، وتقليم أظفاره، ونحو ذلك؛ لأن الرجل الذي أحرم في جُبة، وتلطّخ بالطيب، أمره النبي ﷺ أن يلزم الجبة، ولم يأمره بفدية؛ لجهله، إلا أن عليه الاحتياط في حقه؛ أي يذهب ويسعى فقط احتياطًا خروجًا من الخلاف.\nس: تجديد العقد؟\nالشيخ: إذا جدّد العقد يكون احتياطًا أحسن، خروجًا من خلاف الجمهور.\nس: من بعد التحلل الأول؟\nالشيخ: بعد الطواف، لكن بعد ما سعى سعي الحج، سعي الحج في حق المتمتع فيه خلاف، جماعة يقولون يكفيه السعي الأول، ولكن الصواب أنه لابد من السعي، المتمتع عليه سعيان، فهذا يرجع إلى مكة، ويسعى سعي الحج، وإذا جدّد النكاح يكون احتياطًا، هذا أحسن.\n س: من أتى بعض المحظورات ناسيًا، أو جاهلًا.\nالشيخ: ما عليه شيء؟\nس: هذه قاعدة يا شيخ؟\nالشيخ: نعم، نعم.","link":"https://binbaz.org.sa/fatwas/23592/حكم-من-حج-وترك-السعي-جهلا-منه-منذ-زمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من حج وترك السعي جهلاً منه ومضى زمن.mp3","categories":["السعي"]},{"id":4673,"question":"أخذتُ عمرةً ومعي طفلان صغار، فأحرموا من الميقات، ويوم جاء السعي تعبوا من السعي، هل عليّ شيء؟","title":"ماذا يلزم من اعتمر ومعه طفلان لم يسعيا؟","answer":"الجواب: تسعى بهما فوق سيارة محمولين، الأطفال إذا عجزوا يطوف بهم وليُّهم أو غيره ويسعى بهم، والحمد لله، يُكمل بهم.\nس: ما سعيتُ بهم، أنا الآن عليَّ شيء؟\nج: الظاهر أنه يلزمك أن تعود وتسعى بهما؛ لأنك أنت الذي ألزمت نفسك بهم، وأحرمت عنهم، عليك أن تُكمل وتسعى بهم وتُقصر عنهم، قال الله جلَّ وعلا: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196]، أنت الذي أدخلتهم.","link":"https://binbaz.org.sa/fatwas/24965/ماذا-يلزم-من-اعتمر-ومعه-طفلان-لم-يسعيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اعتمر ومعه طفلان صغار، ولم يسعوا، فماذا يلزم الولي.mp3","categories":["السعي"]},{"id":4689,"question":"بالنسبة للسعي عند الطواف: الهرولة ثلاثة أشواط، وبالنسبة للسعي عند الصفا والمروة إن كان إنسان في رُفقته حرمة، هل يسقط عنه؟","title":"حكم الرمل والهرولة لمن معه نساء","answer":"الجواب: يمشي معها، إذا دعت الحاجةُ للمشي معها يمشي معها، وإن كانت جيدةً وتُكمل طوافها بنفسها فالحمد لله، يُهرول هو والحمد لله.","link":"https://binbaz.org.sa/fatwas/24981/حكم-الرمل-والهرولة-لمن-معه-نساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الهرولة ثلاثة أشواط للسعي.mp3","categories":["السعي"]},{"id":4694,"question":"الحائض تسعى مع دخول المسعى المسجد الحرام؟","title":"حكم سعي الحائض","answer":"الجواب: ولو، ولو، لا بأس، تسعى ولو أنها على غير طهارةٍ، إذا صار الطواف وهي طاهرة فالحمد لله تسعى، ولو أنَّ المسعى داخلٌ ما يضرُّ.","link":"https://binbaz.org.sa/fatwas/24986/حكم-سعي-الحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في سعي الحائض.mp3","categories":["الحيض والنفاس","السعي","قضايا المرأة"]},{"id":4695,"question":"لو قدَّمت المرأةُ السعي على الطَّواف؟","title":"ما حكم مَنْ قدَّمت السعي على الطَّواف؟","answer":"الجواب: المشروع أن تبقى حتى تطوف، السعي بعد الطواف، وهو يُجزئ على الصحيح، لكن المشروع لها أن تبقى حتى تطهر ثم تطوف وتسعى.\nوصحَّ عنه ﷺ أنه سئل: يا رسول الله، سعيتُ قبل أن أطوف؟ قال: لا حرج، لكن السنة أن المؤمن يطوف ثم يسعى كما فعله النبيُّ ﷺ، والحائض تبقى حتى تطهر، فإذا طهرت طافت وسعت.\nس: حديث السائل ما هو خاصّ بتقديم السعي في الحج؟\nج: الرسول لم يستفصل السائل.","link":"https://binbaz.org.sa/fatwas/24987/ما-حكم-من-قدمت-السعي-على-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم لو قدَّمت المرأةُ السعي على الطَّواف.mp3","categories":["السعي","الحيض والنفاس","قضايا المرأة"]},{"id":4696,"question":"في الطواف والسعي بعض الناس يأخذون كتيبات ويُرددونها بصوتٍ جماعي ..؟","title":"حكم الدعاء جهرًا من كتاب في الطواف والسعي","answer":"الجواب: الأحسن أن الإنسان يدعو ربَّه بينه وبين نفسه، لا يُشوش على الناس، ولو معه كتاب يقرأه بينه وبين نفسه، لا يُشوش على الطائفين .......، فإذا تيسر أن يقرأ من نفسه، من كتاب، من شيء بيده، أو يقرأ ما تيسر من حفظه: سبحان الله، والحمد لله، ولا إله إلا الله، أولى من التشويش على الناس، ويكفي: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، إذا كرر هذه في الطواف هذا خير عظيم، أو دعا: اللهم اغفر لي، اللهم ارحمني، اللهم أعتقني من النار، اللهم اغفر لي ولوالدي، اللهم انصر دينك وكتابك وعبادك المؤمنين، يدعو ولا يتكلَّف والحمد لله، ما له حاجة إلى الدَّعوات الكثيرة التي يكتبونها هم ويشغلون بها الناس في الطواف، ما تيسر يكفي من ذكر الله.\nس: يكون هذا الشيء بدعةً؟\nج: الأمر واسع.","link":"https://binbaz.org.sa/fatwas/24988/حكم-الدعاء-جهرا-من-كتاب-في-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء من كتاب في الطواف والسعي، وبصوت جماعي.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":4701,"question":"مَن ركب حال السعي والطواف من غير حاجةٍ ماذا عليه؟","title":"حكم الركوب في السعي والطواف بغير حاجةٍ","answer":"الجواب: الطواف صحيح، والسعي صحيح؛ لأنَّ النبي طاف وهو صحيح، أما حديث ابن عباسٍ أنه اشتكى فهو ضعيف، حديث ابن عباس أنه اشتكى فركب ضعيف، فيه يزيد بن أبي زياد، والصواب أنه ركب لدفع المشقَّة عن الناس؛ لئلا يتأذَّوا أو يُؤذوه.\nس: الشخص العادي الذي يطوف راكبًا من غير سببٍ؟\nج: يُعلَّم أن السنة الطواف ماشيًا.\nوفيه من الفوائد: طهارة البعير، وأنَّ روثه طاهر، وبوله طاهر، البعير لا حرج فيه، ولكن إذا تيسر أن يطوف ماشيًا فهذا هو السنة كما طاف النبيُّ عليه الصلاة والسلام ماشيًا.","link":"https://binbaz.org.sa/fatwas/24993/حكم-الركوب-في-السعي-والطواف-بغير-حاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الركوب حال السعي والطواف من غير حاجةٍ.mp3","categories":["الطواف بالبيت","السعي","الأدعية والأذكار"]},{"id":4702,"question":"الدعاء عند الصَّفا والمروة: إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ [البقرة:158]؟","title":"متى يقال {إِنَّ الصَّفَا..} في السعي؟ وهل يكملها؟","answer":"الجواب: في أول شوط، أول شوط يقول: إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ كما قال النبيُّ ﷺ ثم يصعد.\nس: آية إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ [البقرة:158] يُكملها إلى آخرها؟\nج: فقط إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فقط. ما كمَّلها النبيُّ ﷺ.\nس: يفعل هذا في آخر شوطٍ؟\nج: الشوط الأول عند البدء، هذا السنة.","link":"https://binbaz.org.sa/fatwas/24994/متى-يقال-ان-الصفا-في-السعي-وهل-يكملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يقال إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ، عند الصَّفا والمروة.mp3","categories":["السعي"]},{"id":4703,"question":"رفع اليدين والدعاء حتى في آخر شوطٍ؟","title":"حكم رفع اليدين في الدعاء بالطواف والسعي","answer":"الجواب: نعم، حتى في آخر شوطٍ في الطواف والسعي، كله، في الطواف يرفع يديه ويُكبر في آخر شوطٍ عند الخاتمة، وفي السعي كذلك عند المروة في آخر شوطٍ يرفع يديه ويدعو.","link":"https://binbaz.org.sa/fatwas/24995/حكم-رفع-اليدين-في-الدعاء-بالطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع اليدين والدعاء في الطواف والسعي.mp3","categories":["الطواف بالبيت","السعي","الأدعية والأذكار"]},{"id":4704,"question":"هل يلزمه الصعود إلى الصخور؟","title":"هل يلزم الصعود على الصخور في السعي؟","answer":"الجواب: هذه السنة، وإلا الواجب ما بينهما، لكن الصعود هو السنة.\nس: هل يرقى على الصخرة نفسها أم على المُرتفع المُبلط؟\nج: المعروف الذي يقف عليه الناس الآن.\nس: إذا ما صعد على شيء؟\nج: إذا طاف بينهما أجزأ، والصعود سنة.","link":"https://binbaz.org.sa/fatwas/24996/هل-يلزم-الصعود-على-الصخور-في-السعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يلزم الصعود إلى الصخور في السعي.mp3","categories":["السعي"]},{"id":4721,"question":"مَن كان مُتمتعًا وأُفتي بأنه يُجزئه سعي واحد؟","title":"هل يُجزئ سعي واحد لمَن كان مُتمتعًا؟","answer":"قول ضعيف، هذا قول قاله بعضُ أهل العلم، قول ضعيف، والصواب أنه لا بدَّ من سعي ثانٍ.","link":"https://binbaz.org.sa/fatwas/25018/هل-يجزى-سعي-واحد-لمن-كان-متمتعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكفي سعي واحد لمَن كان مُتمتعًا.mp3","categories":["السعي"]},{"id":4779,"question":"من سعى قبل الطواف جهلًا منه وقصّر من شعره وعمل ما يعمله من أحل الإحرام وهو لا زال بمكة، فماذا عليه وإذا غادر مكة فماذا عليه؟","title":"ما حكم من سعى قبل الطواف جهلًا؟","answer":"لا حرج عليه، إذا سعى قبل الطواف لا حرج عليه، لكن السنة أن يطوف ثم يسعى، وقد ثبت عنه ﷺ أنه سأله رجل فقال يا رسول الله: سعيت قبل أن أطوف؟ فقال: لا حرج السنة أن يطوف ثم يسعى، فلو سعى إنسان جاهلا أو ناسيًا ثم طاف ثم قصر؛ تم الأمر، والحمد لله.","link":"https://binbaz.org.sa/fatwas/25143/ما-حكم-من-سعى-قبل-الطواف-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من سعى قبل الطواف جهلًا.mp3","categories":["السعي"]},{"id":5143,"question":"يقول هذا السائل يا سماحة الشيخ، اعتمرتُ مع والدي، ولكنه لم يستطع إكمال السَّعي بين الصفا والمروة بسبب ألمٍ شديدٍ أصاب ركبته، وقد أكملتُ عنه ثلاثة أشواط، فهل يُجزئ ذلك؟ علمًا بأنه قد قال عند الميقات: فإن حبسني حابسٌ فمحلِّي حيث حبستني، أفيدوني جزاكم الله خيرًا.","title":"حكم من لم يستطع إكمال سعي العمرة لمرضه","answer":"الجواب: لا، ما يُجزئ هذا، وعليه أن يسعى ولو محمولًا، ما تنوب عنه أنت، فيسعى ولو محمول، فإذا كان هذا فعله، فعليه أن يُعيد السَّعي الآن بنية العمرة السَّابقة، ويُعيد التقصير من رأسه، أو الحلق، وإن أتى زوجته فعليه شاة في العمرة، وعليه أن يُعيد العمرة أيضًا، إن كان قد أتى زوجته فجامعها؛ فالعمرة فسدت، وعليه أن يُكملها بالسَّعي ولو محمولًا، وإن كان طاب الحمد لله يمشي يُعيد التَّقصير أو الحلق، ثم يُعيد العمرة كلها من الميقات الذي أحرم بالعمرة الأولى منه؛ لأنَّ العمرة إذا جامع فيها قبل حلّها فسدت، قبل أن يُكمل السعي. فيُكملها بالسَّعي، ويُعيد التقصير والحلق، وتمَّت والحمد لله، وليس عليه شيء، إلا إذا كان قد جامع زوجته بعد هذا؛ فعليه أن يُعيد العمرة مرة أخرى، مع شاةٍ تُذْبَح في مكة للفقراء عن وطئه لها قبل كمال العمرة. وأما أن تكون أنت قد كمَّلْتَ عنه فلا؛ لأنه وجب عليه هو الطَّواف ولو محمولًا على عربةٍ، يقول الله جلَّ وعلا: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196]. ولو كان عاجزًا لا يستطيع أن يصل إلى مكة، ولا يستطيع أن يطوف أو يسعى يُحَجُّ عنه، أما الذي وصل وعرض له عارضٌ في رجله أو في ركبته فهذا يُحْمَل.","link":"https://binbaz.org.sa/fatwas/30058/حكم-من-لم-يستطع-اكمال-سعي-العمرة-لمرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 79.mp3","categories":["السعي"]},{"id":5792,"question":"يا شيخ، عفا الله عنك، صليت المغرب، وذهبت في سيارة أنا وربع معي، وجاء علينا وقت المغرب، فقلت لهم وقفوا نصلي، فوقفنا نصلي، وصليت، وبعد أن صليت تذكرت أني لست على وضوء، وبعد أن رجعت إلى البيت توضأت وصليت، فقال لي أناس: لا تصلي حتى يأتي المغرب عليك، وصلي، وأنا عصيتهم وصليت، وقدمت المغرب؟","title":"من صلى ثم تذكر بعدها أنه على غير طهارة","answer":"الجواب: أحسنت وأخطؤوا، من قال لك: أن ما تصلي المغرب إلا في المغرب الآخر، وما بين الوقتين صلاة، فهذا غلط، فإذا صليت مع الناس، ثم تبين لك... تعيدها في الحال، تتوضأ، وتعيدها في الحال، النبي ﷺ قال: من نام عن الصلاة، أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك هذا فرض، والله قال: وَأَقِمِ الصَّلَاةَ لِذِكْرِي [طه:14].  فالحاصل: أن الإنسان إذا صلى وهو على حدث، ثم تنبه؛ يبادر بالصلاة، يتوضأ ويبادر، أو استيقظ وقد خرج الوقت يبادر، ثم يصلي، ولا يؤخر ولا يؤجل. لكن المسافرين إذا حضر وقت المغرب، وهم في السيارة مسافرون، الأفضل ما ينزلون، الأفضل أن يؤجلوا المغرب مع العشاء هذا الأفضل، كان النبي ﷺ إذا ارتحل قبل دخول المغرب أجل المغرب مع العشاء، وإذا ارتحل قبل الزوال أجل الظهر مع العصر، يجمعها مع العصر.  وهكذا المغرب إذا ارتحل إنسان من مكانه على السيارة، أو على الدابة قبل الغروب يؤجل صلاة المغرب، ما ينزلون ويصلوا المغرب لا، يأجلها مع العشاء هذا السنة.","link":"https://binbaz.org.sa/fatwas/1118/من-صلى-ثم-تذكر-بعدها-انه-على-غير-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_125.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":6310,"question":"هل يجوز لرجل كان عليه غسل جنابة أن يتيمم، ويترك الصلاة، ويوجد الماء، مع العلم أنه إذا اغتسل؛ سوف تفوته صلاة الجماعة، ولم يفته وقت الصلاة؟","title":"حكم تيمم الجنب مع وجود الماء لكي يدرك الجماعة","answer":"الجواب: إذا كان عليه غسل الجنابة؛ يغتسل، ولا يتيمم، ولا يجوز له التيمم، بل يبطل التيمم إذا كان الماء موجودًا، وهو يقدر على استعماله، فيلزمه الغسل، ولو فاتته الجماعة، لو قدر أنه كان .. إذا اغتسل تفوته الجماعة، وإذا تيمم لا تفوته الجماعة لا، لا يتيمم، يغتسل بالماء، ويصلي، ولو في بيته إن ما تيسر له الجماعة. ولكن يجب عليه أن يجعل هناك وقتًا واسعًا، أو يضبط الساعة على وقت واسع، أو يقول للذين يوقظونه قبل الفجر حتى يتمكن من الغسل، والصلاة مع الجماعة، لا يتساهل، والناس -بحمد الله- عندهم ساعات، الآن تيسرت الساعات، يوقتها على الوقت المناسب؛ حتى يقوم في وقت مبكر، ويغتسل على هدوء، ويصلي ما كتب الله له، ثم يتوجه لصلاة الجماعة، هذا الواجب عليه، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1871/حكم-تيمم-الجنب-مع-وجود-الماء-لكي-يدرك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_661.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":6330,"question":"هل يجوز لرجل كان عليه غسل جنابة أن يتيمم، ويترك الصلاة، ويوجد الماء، مع العلم أنه إذا اغتسل؛ سوف تفوته صلاة الجماعة، ولم يفته وقت الصلاة؟","title":"حكم تيمم الجنب مع وجود الماء لكي يدرك الجماعة","answer":"الجواب: إذا كان عليه غسل الجنابة؛ يغتسل، ولا يتيمم، ولا يجوز له التيمم، بل يبطل التيمم إذا كان الماء موجودًا، وهو يقدر على استعماله، فيلزمه الغسل، ولو فاتته الجماعة، لو قدر أنه كان .. إذا اغتسل تفوته الجماعة، وإذا تيمم لا تفوته الجماعة لا، لا يتيمم، يغتسل بالماء، ويصلي، ولو في بيته إن ما تيسر له الجماعة. ولكن يجب عليه أن يجعل هناك وقتًا واسعًا، أو يضبط الساعة على وقت واسع، أو يقول للذين يوقظونه قبل الفجر حتى يتمكن من الغسل، والصلاة مع الجماعة، لا يتساهل، والناس -بحمد الله- عندهم ساعات، الآن تيسرت الساعات، يوقتها على الوقت المناسب؛ حتى يقوم في وقت مبكر، ويغتسل على هدوء، ويصلي ما كتب الله له، ثم يتوجه لصلاة الجماعة، هذا الواجب عليه، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1871/حكم-تيمم-الجنب-مع-وجود-الماء-لكي-يدرك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_661.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":7853,"question":"نبدأ برسالة عتيق بن سلمان العتيق من الرياض، يقول: حججنا ومعنا طالب علم، وكنا نثق به وتمتعنا في حجنا من السيل فطفنا وسعينا وبعد طواف الإفاضة لم نسع، فهل حجنا هذا صحيح أم لا، جزاكم الله عن المسلمين خير الجزاء؟","title":"من تمتع بالعمرة إلى الحج واكتفى بسعي العمرة فقط","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: المتمتع وهو الذي يحرم بالعمرة من الميقات ويفرغ منها ثم يحج من عامه هذا يسمى متمتع في اصطلاح العلماء، وهكذا من أحرم بهما جميعاً بالعمرة والحج جميعاً وبقي على إحرامه حتى حج يسمى متمتعاً أيضاً ويسمى قارناً عند أهل العلم، فهذان عليهما الهدي، هذا الذي أحرم بالعمرة من الميقات وتحلل منها ثم أحرم بالحج يسمى متمتعاً، وذاك الذي أحرم بهما جميعاً من الميقات، ميقات المدينة أو ميقات أهل نجد أو غيرهما واستمر على إحرامه حتى فرغ من حجه كلاهما عليه هدي، والسعي على الذي حل سعي ثاني، والذي لم يحل بل بقي على إحرامه حكمه حكم المفرد الذي حج حجاً مفرداً ليس عليه إلا سعي واحد، والحاصل أن الذي تمتع بالعمرة إلى الحج وتحلل من عمرته يسعى سعياً ثانياً لحجه والسعي الأول يكون لعمرته، هذا هو المشروع، والذي أفتاكم بأنكم لا تسعون أفتى بقول قاله بعض العلماء، ونسأل الله له العفو والمغفرة، ولكن الذي عليه جمهور أهل العلم وهو أرجح القولين أن المتمتع الذي فرغ من عمرته في أشهر الحج ثم أحرم بالحج في عامه أن عليه سعياً ثانياً لحجه والسعي الأول لعمرته، هذا هو المشروع وهذا هو الأرجح، هو أرجح القولين وعليه أكثر أهل العلم، فإذا سمعت -أيها السائل- هذا فعليك أن تسعى عن حجك السابق في هذا الوقت، لا بأس في هذا الوقت أو بعده، عليك أن تسعى عن حجك السابق، وعليك أن تذبح احتياطاً هدي عن جماعك لأهلك إذا كان عندك زوجة وجامعتها بعد الحج، تذبح هدياً في مكة عن جماعك لها قبل أن تسعى صدقة عن إتيانك لزوجتك، تكون في مكة في فقراء الحرم، هذا هو المشروع على سبيل الاحتياط والخروج من خلاف العلماء، وهو الذي دلت عليه السنة، فإن النبي ﷺ لما حج كان أصحابه ثلاثة أقسام: منهم من أحرم بالعمرة وتحلل منها، ومنهم من أحرم بالحج والعمرة جميعاً قارناً، ومنهم من أحرم بالحج وحده، فأمر النبي ﷺ الذين أحرموا بالحج وحده أو بالحج والعمرة جميعاً أن يجعلوها عمرة وأن يتحللوا فأجابوا وسمعوا وأطاعوا وتحللوا، إلا من كان معه الهدي فإنه بقي على إحرامه، وأمر الذين تحللوا من عمرتهم أن يسعوا سعياً ثانياً لحجهم بعدما رجعوا من منى كما رواه البخاري عن ابن عباس رضي الله عنهما، وكما جاء في الصحيحين من حديث عائشة رضي الله عنها أنها قالت: «وأما الذين حلوا من عمرتهم فطافوا طوافاً آخر لحجهم -يعني بين الصفا والمروة» فهذا هو المعتمد. نعم.","link":"https://binbaz.org.sa/fatwas/5243/من-تمتع-بالعمرة-الى-الحج-واكتفى-بسعي-العمرة-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05401.mp3","categories":["الطواف بالبيت","السعي"]},{"id":8718,"question":"إذًا ننتقل إلى مواضيع أخرى حول الحج جزاكم الله خيرًا وفي الحلقات القادمة نستكمل صفة حج النبي ﷺ، نسأل لو تكرمتم كما يسأل السادة المستمعون عن قول الحق تبارك وتعالى: إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا [البقرة:158] الآية، ولم ذكر الجناح في هذه الآية بالذات؟","title":"ما معنى: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ}؟","answer":"الجواب: يقول الله سبحانه: إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ [البقرة:158] الصفا والمروة جبلان معروفان في مكة في طرفي المسعى (من شعائر الله) أي: من معالم دينه، فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا [البقرة:158] فكأن السائل يستشكل: كيف يقال: فَلا جُنَاحَ مع أن العبد مأمور بذلك وفرض عليه أن يسعى؟!\nوالجواب عن ذلك: أن المسلمين تحرجوا من السعي بين الصفا والمروة؛ لأن الجاهلية كانت تسعى بين الصفا والمروة، وكان على المروة صنم وعلى الصفا صنم، فتحرج الناس من ذلك فأنزل الله الآية، وأنه لا جناح على المسلمين لأنهم يسعون ليس كسعي الجاهلية، يسعون لله والأصنام أزالها الله، كسرت الأصنام وأزالها الله على يد نبيه محمد ﷺ التي في المسجد الحرام والتي عند الصفا والمروة وغير ذلك كلها بحمد الله كسرت وأزيلت، فالمسلمون سعوا لله عز وجل طاعة له وتعظيمًا لأمره كما سعى نبيهم ﷺ، فلا جناح عليهم في ذلك وإن كان الجاهلية يفعلون ذلك لكن عمل الجاهلية غير عمل المسلمين، فالجاهلية يتقربون لأصنامهم وأوثانهم بقربات كثيرة، والمسلمون يتقربون إلى الله بسعيهم وطوافهم وصلواتهم وغير ذلك، فبين سبحانه أنه لا جناح على المسلمين في طوافهم بين الصفا والمروة وإن كان ذلك من عمل الجاهلية، لكن العمل الذي يفعله المسلمون لله وحده واتباعًا لنبيه عليه الصلاة والسلام وليس كعمل الجاهلية، فهو واجب وفرض عليهم ولا جناح عليهم فيه ولا حرج عليهم فيه وإن كانت الجاهلية فعلته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6869/ما-معنى-ان-الصفا-والمروة-من-شعاىر-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_160/16003.mp3","categories":["السعي"]},{"id":8731,"question":"رسالة وصلت إلى البرنامج من أختنا أم أحمد عبده من تعز، أختنا رسالتها مطولة بعض الشيء وتقول فيها: إني أضع مشكلتي هذه التي سببت لي القلق والحيرة آملة عدم إهمال الرد على مشكلتي وهي: ذهبت إلى الحج وقد خرجت من بيتي ومعي أربع نساء من الحي مع إخوانهن وكذلك كان ابني برفقتي من بيتي إلى المطار إلى أن وصلت إلى جماعة النساء واللائي كان معهن إخوانهن، واستقبلني زوجي في المطار وبعد ذلك قمنا بالبدء بأداء شعائر الحج، وحل وقت العيد ورميت الجمرات يوم العيد وثاني العيد وكلت زوجي، وثالث العيد قلت لزوجي: أريد أن أرمي الجمرات فمانع لشدة الزحام، وعلى إثر ذلك وقع بيننا شيء من الخصام فلم أوكله ولم أرم الجمرة ولم أطف أيضًا طواف الوداع نتيجة ما حصل بيننا، والآن أنا قلقة على ذلك النقص الذي حصل مني، أرجو أن توجهوني جزاكم الله خيرا؟","title":"حكم من حج وترك رمي الجمرات وطواف الوداع","answer":"الجواب: الحج صحيح والحمد لله، ولكن عليك فديتان:\nإحداهما: عن ترك الرمي تذبح في مكة ذبيحة من الغنم كالضحية؛ إما جذع ضأن أو ثني معز تذبح في الحرم في مكة وتوزع بين الفقراء.\nوالفدية الثانية: عن طواف الوداع؛ لأنك سافرت ولم تودعي، وظاهر كلامك أنك سافرت بدون محرم من بلدك إلى مطار جدة، وأن ابنك معك إلى المطار ثم تلقاك زوجك في المطار في جدة، وأنت معك نسوة، وهذا إن كان صحيحًا ما ظهر من سؤالك هو لا يجوز، ليس للمرأة أن تسافر إلا مع ذي محرم، ولو أن معها من يصحبها إلى المطار ويتلقاها في المطار؛ الرسول عليه السلام قال: لا تسافر امرأة إلا مع ذي محرم فإن كان هذا هو الواقع وأنك سافرت بدون محرم فعليك التوبة إلى الله والاستغفار وعدم العود إلى مثل هذا، والحج صحيح والحمد لله، وعليك ما ذكرنا من الفديتين: ذبيحة عن ترك الرمي، وذبيحة أخرى عن ترك الوداع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6882/حكم-من-حج-وترك-رمي-الجمرات-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/16104.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":9120,"question":"السؤال الثالث في رسالة الإخوة: علي محمد فارع اليماني وعلي حسن عبده وعبد الرحمن محمد علي صالح من الجمهورية العربية اليمنية، يقولون فيه:أهل مكة والمتمتع هل يجوز لهم الطواف والسعي قبل الصعود إلى عرفات دون الخروج إلى الحِلْ، أم أنه لا بد من الذهاب إلى الحِلْ والإحرام منه ليتسنى لهم أداء طواف القدوم وسعي الحج قبل الحج، وما حكم من فعل ذلك دون خروج إلى الحل أفيدونا أفادكم الله؟","title":"حكم الطواف والسعي لأهل مكة والمتمتعين إذا أرادوا الحج","answer":"الجواب: أهل مكة وغيرهم من المتحللين من العمرة في مكة السنة لهم إذا أحرموا أن يتوجهوا إلى منى، سواء كان إحرامهم من الحِل أو من الحرم.\nالسنة لهم أن يتوجهوا إلى منى كما توجه النبي ﷺ وأصحابه رضي الله عنهم إلى منى يوم الثامن، فالنبي ﷺ أمر الصحابة أن يتوجهوا إلى منى يوم الثامن وأن يحرموا بالحج، ولم يقل لهم: ادخلوا إلى مكة فطوفوا واسعوا أو طوفوا فقط بل أمرهم بأن يتوجهوا إلى منى ملبين، فدل ذلك على أن المتحلل في مكة من العمرة وهكذا أهل مكة إذا أرادوا الحج وهكذا المقيمون بها إذا جاء يوم الثامن وهم يريدون الحج يحرمون من منازلهم أو من أي مكان ويتوجهون إلى منى، ولا يشرع لهم دخول مكة للطواف والسعي، وإنما هذا للأفقي الذي قدم.. الذي يقدم من بعيد هذا يشرع له أن يبدأ بالطواف والسعي ثم يتحلل بالعمرة إن كان الوقت فيه سعة، وإن كان الوقت ضيقاً ذهب إلى منى على إحرامه، سواء كان محرماً بالحج أو بالقران، أما إن كان محرماً بالعمرة فقط وهو المتمتع فإنه بعد الطواف والسعي يقصر أو يحلق، والسنة التقصير إذا كانت العمرة قريبة من الحج حتى يتوفر الحلق للحج.\nوبعدما يقصر من عمرته يلبي بالحج ثم يتوجه إلى منى ولا يطوف ويسعى بعد تلبيته بالحج، بل يلبي بالحج ويخرج حالاً إلى جهة منى من غير طواف ولا سعي وهذا الطواف والسعي الذي يفعله المحرم من مكة في الحج، لا يجزئه إذا طاف وسعى بعدما أحرم في مكة بالحج لا يجزئه؛ لأنه غير مشروع وإنما الطواف والسعي يكون بعد ذلك بعد نزوله من عرفات يوم العيد أو بعده هذا هو الطواف المشروع لمن أحرم من مكة من أهلها أو المقيمين فيها أو المتحللين والله ولي التوفيق.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7278/حكم-الطواف-والسعي-لاهل-مكة-والمتمتعين-اذا-ارادوا-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_228/22803.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":9467,"question":"ورد سؤال من الأخ عيسى عبدالوهاب من السودان يقول فيه: قرأت في بعض المناسك: لو سعى قبل أن يطوف جهلًا أو ناسيًا فلا شيء عليه مستدلًا بحديث: سعيت قبل أن أطوف، قال: افعل ولا حرج فهل هذا صحيح؟ وما مدى صحة هذا الحديث، أفيدونا وفقكم الله؟","title":"حكم تقديم السعي على الطواف","answer":"الجواب: نعم صحيح، وقد بيناه في المنسك منسكنا (التحقيق والإيضاح في كثير من مسائل الحج والعمرة والزيارة)، والحديث في الصحيح عن النبي ﷺ أنه سأله سائل، فقال: سعيت قبل أن أطوف؟ قال: طف ولا حرج ولم يأمره بإعادة السعي، فدل ذلك على أنه لا حرج في ذلك ولاسيما إذا كان جاهلًا أو ناسيًا، فالأمر فيه أوضح وقال في الحديث: ولو عامدًا، وهذا أيضًا يعمه قوله ﷺ في الحديث الصحيح لما سئل يوم النحر: قال له: يا رسول الله! حلقت قبل أن أذبح؟ قال: اذبح ولا حرج، وقال آخر: نحرت قبل أن أرمي؟ قال: لا حرج، وقال آخر: أفضت قبل أن أرمي؟ قال: لا حرج، قال الراوي: فما سئل يومئذ عن شيء قدم ولا أخر إلا قال: افعل ولا حرج.\nفهذا العموم يعم من سعى قبل أن يطوف، وأنه يجزئه ذلك كما يجزئه لو نحر قبل أن يرمي أو طاف قبل أن يرمي، مع أن النبي ﷺ رمى ثم نحر ثم حلق ثم طاف، رتب هكذا، رمى ثم نحر ثم حلق ثم طاف، ولكن هذا الترتيب بين ﷺ أنه ليس بواجب، ولكنه هو الأفضل، فمن قدم بعض على بعض فلا حرج، سواء كان عامدًا أو جاهلًا أو ناسيًا، فيدخل في ذلك الطواف والسعي أيضًا، فإذا سعى قبل أن يطوف ناسيًا أو جاهلًا فلا حرج بلا شك، وهكذا لو كان عامدًا على الصحيح لعموم قوله ﷺ للرجل لما سأله: سعيت قبل أن أطوف؟ قال: لا حرج ولم يسأله يقول: هل أنت ناسي؟! هل أنت جاهل؟! بل أطلق، والإطلاق يدل على التعميم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7629/حكم-تقديم-السعي-على-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19110.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":10061,"question":"إذا كنت لا أحفظ كثيراً من الأدعية، فهل يجوز أن أتناول كتاباً يحتوي على بعض الأدعية وأقرأ منه وأنا أطوف بالبيت الحرام وفي المسعى مثلاً؟","title":"حكم قراءة الأدعية أثناء الطواف والسعي من كتاب","answer":"الجواب: لا حرج في ذلك الحمد لله، لا حرج، أن تأخذ كتاباً فيه دعوات طيبة من مؤلف معروف موثوق به من العلماء لا بأس، أو تدعو على أن تدعو من قلبك يعني: عن ظهر قلب مما يسر الله لك قد يكون هذا أجمع لقلبك قد يكون هذا أخشع وإن دعوت من ورقة أو كتاب فلا بأس. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8232/حكم-قراءة-الادعية-اثناء-الطواف-والسعي-من-كتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30314.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":10537,"question":"السائلات مقيمات في منطقة جدة يقلن في هذا  نرجو الإفادة الحكم لمن لم يتم العمرة وذلك في شهر رمضان في اليوم السابع والعشرين من الشهر الكريم، فقد أدينا الطواف كاملًا ولكننا لم نستطع إتمام السعي؛ وذلك لشدة الزحام فما الحكم في ذلك؟ وهل هناك فدية، وما نوع الفدية وأين ذبحها سماحة الشيخ؟","title":"حكم من لم يتم السعي في العمرة لشدة الزحام","answer":"الجواب: الواجب تكميل العمرة بعد تلك الليلة، يسعى ويقصر ويحلق هذا هو الواجب على الجميع الرجال والنساء، لا بأس .. بأن يكون بين الطواف والسعي فجوة، فإذا طاف مثلاً في النهار وصعب عليه السعي، أو طاف في الليل وصعب عليه السعي، أجل السعي إلى وقت آخر وسعى والحمد لله، والذي ما سعى مثلاً إلى الآن يسعى يذهب ويسعى يكمل عمرته ويقصر؛ لأنه ما زال في إحرام العمرة، إذا كان لم يسع ولم يقصر لا يزال في إحرام العمرة إلى أن يرجع إلى مكة ويسعى ويقصر ويتحلل والحمد لله.\nوإن كان أتى زوجته إذا كان رجل أو امرأة أتاها زوجها فهي تفسد العمرة، وتكملها عمرة فاسدة وتأتي بعمرة جديدة من الميقات الذي أحرمت بالأولى منه، وهذه العمرة التي وقع فيها جماع تكمل فاسدة، ثم يؤتى بعمرة عوضاً منها من الميقات الذي أحرم بالأولى منه، نعم.\nالمقدم: سماحة الشيخ الحقيقة استوقفني مقطع من هذا السؤال، وهو التزاحم يوم السابع والعشرين من شهر رمضان هل من كلمة حول هذا سماحة الشيخ؟\nالشيخ: نعم، لا شك أن هذا أمر يحصل به مضرة كبيرة، والذي ينبغي للمؤمنين في هذا عدم التزاحم، وإذا كان مشقة يؤجل يطوف في النهار، يسعى في النهار، ليس من اللازم أن يسعى في الليل، يشق على نفسه وعلى غيره، والحمد لله يجتهد فيها بالتسبيح والتهليل والدعاء وأنواع الخير والذكر والقراءة ويكفي، ولا يؤذي نفسه ولا يؤذي الناس، الرجل والمرأة جميعاً، فلا حاجة إلى الزحام الذي يضرهم جميعاً، يبقى على إحرامه ويطوف ويسعى في النهار والحمد لله، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8712/حكم-من-لم-يتم-السعي-في-العمرة-لشدة-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28409.mp3","categories":["الطواف بالبيت","السعي"]},{"id":10857,"question":"يقول: والدتي كبيرة في السن، طافت بالبيت العتيق، وأرادت أن تسعى، لكنها لا تستطيع، فركبت عربية وحينئذ غفت عينها، ولم تستيقظ إلا بعد انتهاء السعي، فهل سعيها صحيح؟","title":"حكم من عجز عن السعي فحُمل ونام ولم يستيقظ إلا بعده","answer":"الجواب: \n\nلا يصح إذا كان نامت، لا يصح سعيها، أما إذا كان نعاسًا لكن ما ذهب شعورها، فالنعاس لا يضر، كما قد يقع للإنسان في الصلاة أيضًا، أما إذا قد ذهب يعني نامت نومًا يزيل الشعور فإن النية تزول ما تمت النية، لا بد من أن تسعى بنية السعي، وهي عاقلة، شعورها معها، فإذا فاتها شوطٌ أو شوطان في النوم تعيد الشوط والشوطين الذي نامت فيهما، وإن كان السعي كله ذهب في النوم تعيده كله. \n\nالمقصود: أنه إذا كان نعاسًا وشعورها باقيًا فلا بأس، أما إذا كانت نامت في الأشواط كلها تعيدها، أو نامت في شوط، أو شوطين، أو ثلاثة تعيد الشوط الذي نامت فيه نومًا ثقيلًا، نومًا أفقدها الشعور. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9040/حكم-من-عجز-عن-السعي-فحمل-ونام-ولم-يستيقظ-الا-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35708.mp3","categories":["الطواف بالبيت","السعي"]},{"id":11296,"question":"يقول في سؤال ثانٍ: أديت فريضة الحج منذ ثلاث سنوات وطفت طواف القدوم وسعيت بين الصفا والمروة، وأيضًا طفت طواف الوداع ولم أسع بين الصفا والمروة لأني كنت لا أعلم ذلك، وعندما توجهت إلى المدينة المنورة لزيارة الحرم النبوي الشريف علمت من الإخوة بأن المفروض علي السعي بين الصفا والمروة بعد طواف الوداع، وبعض منهم نصحني بفدية، والبعض الآخر قال بأنه لا شيء عليك إذا كنت تجهل ذلك، هل حجي صحيح أم أن علي فدية أم ماذا أفعل؟ جزاكم الله خيرًا. الشيخ: تعيده. نعم.المقدم: يقول: أديت فريضة الحج منذ ثلاث سنوات وطفت طواف القدوم وسعيت بين الصفا والمروة، وأيضًا طفت طواف الوداع ولم أسع بين الصفا والمروة لأني كنت لا أعلم ذلك، وعندما توجهت إلى المدينة المنورة لزيارة الحرم النبوي الشريف علمت من الإخوة بأن المفروض علي السعي بين الصفا والمروة بعد طواف الوداع، وبعض منهم نصحني بالفدية، والبعض الآخر قال بأنه لا شيء عليك إذا كنت تجهل، هل حجي صحيح أم أن علي فدية أم ماذا أفعل؟ جزاكم الله خيرًا.","title":"حكم من ترك السعي في الحج مكتفياً به في العمرة","answer":"الجواب:  سؤالك فيه إجمال وعدم تفصيل، لكن نفصل لك حتى تعرف الواقع، إذا كنت لبيت بالعمرة ودخلت بالعمرة وطفت وسعيت وقصرت وحليت من العمرة متمتعًا، ثم لبيت بالحج وحججت مع الناس، وطفت طواف الإفاضة، وطفت طواف الوداع ولكن لم تسع، فهذا غلط منك عليك أن تسعى ولو الآن، عليك أن تذهب إلى مكة تسعى بنية الحج السابق ولا حرج عليك تسعى بنية الحج السابق، وعليك فدية إذا كنت جامعت المرأة بعد ذلك، ذبيحة تذبح في مكة للفقراء؛ لأنك أتيت المرأة قبل أن تسعى بفعل الحج والسعي الأول للعمرة، أما السعي الثاني فهو عليك للحج مع طواف الإفاضة الذي تأتي به بعد قدومك من منى يوم العيد أو بعده، أما طواف الوداع فمستقل عند الخروج من مكة، طواف الوداع هذا مستقل واجب لتوديع البيت عند الخروج من مكة، وعليك أن تمتنع من الجماع حتى تأتي بالسعي. أما إذا كنت لبيت بالحج أو بالحج والعمرة جميعًا بقيت على إحرامك، طفت وسعيت وبقيت على إحرامك ما حللت حتى خرجت إلى منى وأنت محرم فلا عليك شيء، يكفيك الطواف طواف الإفاضة غير طواف الوداع، طواف الإفاضة ثم طواف الوداع عند الخروج، وإن طفت طواف الإفاضة عند الخروج كفى عن الوداع، إذا كنت طفت عند الخروج طوافًا واحدًا سبعة أشواط كفى عن الوداع، وليس عليك السعي، السعي الأول كافي إذا كنت أحرمت بالحج مفردًا أو بالحج والعمرة جميعًا ولم تحل بل بقيت على إحرامك حتى ذهبت إلى منى وحتى أديت الحج فليس عليك إلا السعي الأول، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9473/حكم-من-ترك-السعي-في-الحج-مكتفيا-به-في-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37605.mp3","categories":["الطواف بالبيت","السعي"]},{"id":11309,"question":"يسأل في قضية يقول: هل يجوز للمرأة أن تقبل الحجر الأسود وتستلم الركن اليماني؟","title":"حكم تقبيل المرأة للحجر الأسود واستلام الركن اليماني","answer":"الجواب:  إذا تيسر ذلك من دون مزاحمة للرجال ولا فتنة، إذا تيسر في وقت خلوة ..... بين الرجال فلا بأس وإلا فإنها تطوف من وراء الناس في أطراف المطاف بعدًا عن الفتنة، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9497/حكم-تقبيل-المراة-للحجر-الاسود-واستلام-الركن-اليماني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37708.mp3","categories":["الطواف بالبيت","السعي","قضايا المرأة"]},{"id":11324,"question":"يسأل في قضية يقول: هل يجوز للمرأة أن تقبل الحجر الأسود وتستلم الركن اليماني؟","title":"حكم تقبيل المرأة للحجر الأسود واستلام الركن اليماني","answer":"الجواب:  إذا تيسر ذلك من دون مزاحمة للرجال ولا فتنة، إذا تيسر في وقت خلوة ..... بين الرجال فلا بأس وإلا فإنها تطوف من وراء الناس في أطراف المطاف بعدًا عن الفتنة، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9497/حكم-تقبيل-المراة-للحجر-الاسود-واستلام-الركن-اليماني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37708.mp3","categories":["الطواف بالبيت","السعي","قضايا المرأة"]},{"id":11369,"question":"أخونا يقول: الحمد لله قد أديت فريضة الحج واعتمرت، لكنني كنت أسعى من الصفا إلى المروة وأعود فأعتبر هذا شوطًا واحدًا، وهكذا قضيت الأشواط السبعة، فهل في هذه الزيادة شيء؟ أفيدوني جزاكم الله خيرًا.","title":"حكم الزيادة في أشواط السعي بين الصفا والمروة","answer":"الجواب:  السعي صحيح والسبعة الزائدة لا تضرك، السعي المشروع من الصفا إلى المروة شوط والعودة من المروة إلى الصفا شوط ثاني وهكذا، فإذا سعى أربعة عشر فالمشروع منها سبعة والزائد لا يضره لأنه وقع خطأً منه وجهلًا منه فلا يضره. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9567/حكم-الزيادة-في-اشواط-السعي-بين-الصفا-والمروة","audio":"","categories":["الطواف بالبيت","السعي"]},{"id":11377,"question":"أخونا يقول: الحمد لله قد أديت فريضة الحج واعتمرت، لكنني كنت أسعى من الصفا إلى المروة وأعود فأعتبر هذا شوطًا واحدًا، وهكذا قضيت الأشواط السبعة، فهل في هذه الزيادة شيء؟ أفيدوني جزاكم الله خيرًا.","title":"حكم الزيادة في أشواط السعي بين الصفا والمروة","answer":"الجواب:  السعي صحيح والسبعة الزائدة لا تضرك، السعي المشروع من الصفا إلى المروة شوط والعودة من المروة إلى الصفا شوط ثاني وهكذا، فإذا سعى أربعة عشر فالمشروع منها سبعة والزائد لا يضره لأنه وقع خطأً منه وجهلًا منه فلا يضره. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9567/حكم-الزيادة-في-اشواط-السعي-بين-الصفا-والمروة","audio":"","categories":["الطواف بالبيت","السعي"]},{"id":12250,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الطائف، وقعت في نهاية الرسالة بقولها: أختكم في الله نالة العسيري، الأخت نالة عرضنا بعض أسئلةٍ لها في حلقاتٍ مضت، وفي هذه الحلقة سنعرض لها بعضًا من أسئلتها أيضًا، حيث بعثت بعددٍ كبيرٍ من الأسئلة، فتسأل في هذه الحلقة، وتقول: هل للطواف والسعي بين الصفا والمروة، والوقوف بعرفة، والمبيت بمزدلفة، أدعية مخصصة، أم يدعو الحاج بما شاء من الأدعية؟","title":"الأدعية والأذكار المشروعة في الطواف والسعي","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فليس للطواف والسعي والوقوف بعرفة، وفي مزدلفة أدعية مخصصة، لابد منها، بل يشرع للمؤمن أن يدعو ويذكر الله، وليس هناك حد محدود، فيذكر الله بقوله: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيءٍ قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده، سبحان الله العظيم، يردد مثل هذا الذكر، ويدعو بما يسر الله من الدعوات، يسأل ربه أن الله يغفر له ذنوبه، ويدخله الجنة، وينجيه من النار، يسأل الله له ولوالديه المسلمين المغفرة والرحمة، وإن كان والداه مسلمين؛ سأل الله لهما التوفيق في إصابة الحق، والهداية والاستقامة، والثبات على دين الله. وهكذا يسأل الله لولاة أمر المسلمين بالتوفيق والهداية، وصلاح النية والعمل، وصلاح البطانة، ويسأل الله من خير الدنيا والآخرة، في طوافه، وفي سعيه، وفي وقوفه بعرفات، وفي مزدلفة، وفي منى، وفي كل مكان، يسأل ربه من خير الدنيا والآخرة. لكن يشرع له في الطواف أن يختم كل شوط بقوله: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] فعله الرسول ﷺ وهذا مستحب، ولو ترك؛ ما عليه شيء، فهذا مستحب أن يقول هذا الدعاء، ولو ما دعا بذلك، ودعا بغيره؛ فلا حرج عليه، لكن يستحب له في آخر كل شوط بين الركنين، يعني: بين الركن اليماني، والحجر الأسود أن يقول: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] وكلما حاذى الحجر؛ كبر، قال: الله أكبر، أو باسم الله والله أكبر، في كل طوفة، يبدأ بهذا، ويختم بهذا، يبدأ بالتكبير، ويختم بالتكبير، وإن قرأ القرآن في سعيه وطوافه، فلا بأس، وفي السعي يستحب له أن يكثر من الدعاء والذكر والتكبير، على الصفا والمروة، مستقبلًا القبلة ثلاث مرات، يكرر ثلاث مرات، والرسول ﷺ .......... وحد الله وكبره، ودعا، وكرر ثلاث مرات، وكان من ذكره على الصفا والمروة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيءٍ قدير، لا إله إلا الله وحده، أنجز وعده، ونصر عبده، وهزم الأحزاب وحده. ويدعو بما يسر الله، ويكرر ثلاث مرات، وإذا قال: الله أكبر الله أكبر، لا إله إلا الله، الله أكبر، الله أكبر ولله الحمد، هذا طيب؛ لأن فيه تحميد الله، وتكبيره؛ لأن في هذا تحميد الله وتكبيره . وإن قال: سبحان الله والحمد لله، ولا إله إلا الله، والله أكبر؛ فحسن، أو قال: سبحان الله وبحمده، سبحان الله العظيم؛ فحسن، يدعو بما تيسر، ويدعو ما تيسر، مع الذكر، ويرفع يديه، ويستقبل القبلة حال كونه على الصفا وحال كونه على المروة، يستقبل القبلة رافعًا يديه، ويكبر الله، ويحمده، ويثني عليه، ويدعو، ويذكر الله ثلاث مرات، يكرر، كما كرر النبي، عليه الصلاة والسلام. وهكذا على المروة، في كل شوط، ويختم بالذكر والدعاء على المروة في الشوط السابع، وفي الطريق بينهما يذكر الله، ويدعو أيضًا، بما يسر الله من ذكرٍ وثناء، وحمدٍ ودعاء، حين نزوله من الصفا إلى المروة، وحين رجوعه كذلك من المروة إلى الصفا، يكثر من ذكر الله والدعاء، وليس في ذلك شيء معين واجب، بل ما يسر الله له من الذكر والدعاء الطيب، فهو كافي، لكن يتحرى الدعوات الجامعة، التي تنفعه في الدنيا والآخرة، مثل: اللهم إنك عفو تحب العفو فاعف عني اللهم إني أسألك رضاك والجنة، وأعوذ بك من سخطك والنار اللهم إني أسألك الجنة، وما قرب إليها من قولٍ وعمل، وأعوذ بك من النار، وما قرب إليها من قول وعمل رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] إلى غير هذا، مع ذكر الله، مع قوله: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت وهو على كل شيء قدير سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، الله أكبر الله أكبر، لا إله إلا الله، الله أكبر، الله أكبر ولله الحمد، الله أكبر كبيرًا، والحمد لله كثيرًا، وسبحان الله بكرةً وأصيلًا، يكثر من هذا الذكر، ومن الدعاء، في سعيه وطوافه، وهكذا في يوم عرفة، إذا وقف بعد صلاة الجمع، الظهر العصر، يقف بعرفة مستقبلًا القبلة، ويرفع يديه في أي جزء منها كل عرفة موقف، في أي مكانٍ .... يرفع يديه، ويلح في الدعاء، ويكثر من الدعاء، ويكثر من الصلاة على النبي ﷺ .... في دعائه.  فإن حمد الله، والثناء عليه، والصلاة على النبي ﷺ من أسباب الإجابة، فيكثر في دعواته من الصلاة على النبي ﷺ، مع حمد الله، مع الثناء على الله، يصلي على النبي ﷺ في الصفا وفي المروة وفي عرفة وفي مزدلفة، وفي جميع أدعيته، في كل مكان، والبداءة بالحمد والثناء مع الصلاة على النبي ﷺ من أسباب الإجابة، كما في حديث فضالة بن عبيد : أن النبي ﷺ سمع رجلًا دعا، ولم يحمد الله، ولم يصل على النبي ﷺ قال: عجل هذا ثم قال: إذا دعا أحدكم؛ فليبدأ بتحميد ربه، والثناء عليه، ثم يصلي على النبي ﷺ ثم يدعو بما شاء فدل ذلك على أنه إذا بدأ بالحمد، والتمجيد، والثناء على الله، ثم بالصلاة على النبي ﷺ كان هذا من أسباب الإجابة. ومن ذلك: الخشوع والإقبال على الله، حضور القلب، كونه يدعو بقلبٍ حاضر، يعظم الله، ويخضع له، ويعلم أنه مجيب الدعاء، وأنه جواد كريم، وأن العبد فقير إليه، وأنه الغني الحميد سبحانه، إحضار القلب، والشعور بأنك عبد ذليل، وأن الله هو الحكيم العليم، وهو العلي الكبير، مستحق لأن تعبده، وتخضع له، هذا من أسباب الإجابة. وهكذا في صلاتك، في أيام الحج وغير الحج، تكثر من الدعاء في السجود، وفي آخر الصلاة قبل أن تسلم بعد التشهد، تكثر من الدعاء أيضًا في صلواتك؛ لأنها محل إجابة. هكذا بين الأذان والإقامة، إن أذن تكثر من الدعاء بين الأذان والإقامة، وتحمد الله، وتصلي على النبي ﷺ، ثم تدعو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10450/الادعية-والاذكار-المشروعة-في-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44901.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":12351,"question":"هل يصح كشف الوجه للمرأة في المسجد الحرام، أو في السعي، أو أثناء الطواف؟","title":"حكم كشف المرأة وجهها أثناء الطواف والسعي","answer":"الجواب:  ليس لها ذلك، عليها الحجاب في الطواف والسعي وفي جميع الأوقات، إذا كان حولها رجال أجناب، أما إذا كان ما عندها أجنبي؛ فيجوز أن تكشف، الأفضل لها تكشف في صلاتها، لكن إذا كانت في الطواف في السعي الرجال عندها؛ عليها أن تحتجب، وهكذا في مواضع الرجال، ولو رجلًا واحدًا، لقوله -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وقوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، والوجه من أعظم الزينة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10552/حكم-كشف-المراة-وجهها-اثناء-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39911.mp3","categories":["الطواف بالبيت","السعي"]},{"id":12977,"question":"المستمع (ع. ص. س) بعث يسأل ويقول: حجيت وقمت بالطواف أكثر من سبعة أشواط، وكذلك السعي، ورميت الجمرات أكثر من سبع حصيات، فهل حجي صحيح؟","title":"حكم الزيادة في الطواف والسعي والرمي في الحج","answer":"الجواب:  نعم الحج صحيح، إذا كان ما فعلت شيئًا يبطله، أما الزيادة فلا تضر، إذا كنت تعمدت الزيادة هذا غلط، عليك التوبة والاستغفار؛ لأن السنة سبع في الجمار، وسبع في الطواف، وسبع في السعي. فالزيادة التي فعلتها إن كان عن احتياط، شكيت أو احتطت؛ فلا بأس، أما إذا كان تعمدًا منك فهذا لا يجوز الزيادة على ما شرعه الله، ولكن لا يبطل الطواف، ولا السعي، ولا الرمي، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11194/حكم-الزيادة-في-الطواف-والسعي-والرمي-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47009.mp3","categories":["الطواف بالبيت","السعي"]},{"id":13043,"question":"هذا السائل علي عبدالرحمن يقول: هل عليَّ سعي بعد طواف الإفاضة، علمًا بأنني قارن، وسعيت بعد طواف القدوم، فأفيدوني بذلك؟","title":"حكم السعي بعد الإفاضة لمن سعى مع طواف القدوم","answer":"الجواب:  القارن والمفرد ليس عليه إلا سعي واحد، إذا قدم مكة، وطاف، وسعى، وبقي على إحرامه حتى حج؛ ليس عليه شيء آخر، طوافه وسعيه الأول يكفيان عن السعي، يبقى عليه طواف الإفاضة، إذا كان القارن، أو المفرد سعيا مع طواف القدوم، كفاهم السعي الأول، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/11260/حكم-السعي-بعد-الافاضة-لمن-سعى-مع-طواف-القدوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50503.mp3","categories":["الطواف بالبيت","السعي"]},{"id":13271,"question":"يقول هذا السائل: هل يلزم الطهارة في السعي والطواف؟","title":"حكم اشتراط الطهارة في الطواف والسعي","answer":"الجواب:  الطهارة لابد منها في الطواف، الطواف صلاة كما قال ابن عباس -رضي الله عنهما-: الطواف بالبيت صلاة إلا أن الله أباح فيه الكلام تقول عائشة -رضي الله عنها-: لما قدم النبي مكة -عليه الصلاة والسلام- وأتى المسجد الحرام، توضأ ثم طاف فالطواف بالبيت صلاة، يتوضأ ثم يطوف. أما السعي لا، إن طاف بطهارة؛ فهو أفضل، وإن سعى على غير طهارة؛ فلا حرج، أما الطواف بالكعبة لابد من الطهارة كالصلاة، يطوف متطهرًا، ثم يصلي ركعتين. أما السعي بين الصفا والمروة فهذا إن تطهر فهو أفضل، وإن سعى على غير طهارة؛ فلا حرج؛ ولهذا لو سعت الحائض والنفساء؛ صح سعيها، بخلاف الطواف، فلو طافت المرأة وهي طاهرة، ثم حاضت بعد الطواف؛ سعت ولا حرج. نعم.","link":"https://binbaz.org.sa/fatwas/11555/حكم-اشتراط-الطهارة-في-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51407.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":13462,"question":"هذا السائل (م. ع. م) يقول: سماحة الشيخ! قمت أنا وزوجتي بأداء العمرة في سنة ماضية، وفي أثناء السعي أتتها الدورة الشهرية -الحيض- فسألنا أحد الإخوان فقال: يجب عليكم أن تعيدوا العمرة مرة أخرى، ولا يلزمكم البقاء في مكة، وإعادتها ولو بعد شهر أو شهرين، وسؤالنا يا سماحة الشيخ: هل ما أفتانا به الأخ صحيح؟ وماذا يجب علينا أن نعمل؟","title":"حكم من أتتها الدورة الشهرية أثناء السعي","answer":"الجواب: الواجب عليكم تكميل سعي العمرة، تكميلها، إذا كانت المرأة سعت بعض السعي؛ عليها أن تعود، وتكمل السعي، وإن بدأته من أول يكون أحوط، تبدأ السعي وتكمل، والسعي لا يشترط له الطهارة، الطهارة شرط للطواف، أما السعي لو حاضت في السعي ما يضر، أو طافت بغير وضوء لا بأس -يعني: السعي- إنما الطهارة تشترط في الطواف بالكعبة، أما الطواف بين الصفا والمروة وهو السعي؛ فهذا لا يشترط له الطهارة، فإذا كنتم خرجتم من مكة، ولم تكملوا السعي، عليكم أن ترجعوا وتكملوا السعي، ثم التقصير للمرأة، والحلق للرجل، أو التقصير، وتمت العمرة ما يحتاج إعادة للعمرة، يحتاج إعادة السعي الذين ما تميتمونه. عليكم أن ترجعوا وتكملوا السعي، ثم يحلق الرجل أو يقصر، وتقصر هي وتمت العمرة والحمد لله، إلا أن يكون الرجل جامع زوجته؛ فإنه يتم العمرة ويعيدها؛ لأن الجماع يبطل العمرة، فإذا كان جامعها بعدما رجعا قبل أن يكمل السعي، فإنهما يرجعان ويكملان السعي ويقصران، أو يحلق الرجل وتقصر المرأة، ثم بعد ذلك يحرمان بالعمرة من جديد، من الميقات الذي أحرموا الأولى منه من جديد، ويأتون بعمرة جديدة بدل هذه العمرة التي أفسدوها، نعم.","link":"https://binbaz.org.sa/fatwas/11765/حكم-من-اتتها-الدورة-الشهرية-اثناء-السعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51710.mp3","categories":["قضايا المرأة","السعي"]},{"id":14804,"question":"المستمع: (خ .م . د) بعث برسالة وضمنها عددًا من الأسئلة، له سؤال طويل جدًا يقول فيه:في عام ألف وأربعمائة وسبعة، أديت فريضة الحج مع زوجتي، وهي كانت حامل، وأديت جميع المناسك الحمد لله بيسرٍ وسهولة، ولكن عند رجم الشيطان في اليوم الثاني، لم أتمكن من رمي الجمرة الثالثة، وكانت زوجتي قد وكلتني برمي جميع الجمرات لها؛ لأنها لم تتمكن من رميها، فإني حائر، وسألت عدة أشخاصٍ عن ذلك، بعضهم يقول لي: حجك صحيح، والبعض يقول لي: يتوجب عليك أن تذبح هدي؛ علمًا بأنني ذبحت هديًا واحدًا فقط لي، وهذا كان أول يوم العيد، قبل أن أرمي الجمرة الثانية؛ لأني قلت: يمكن أنني أنقصت شيئًا من المناسك، وحيث أنني لم أتمكن من رمي الجمرة الثالثة في اليوم الثاني، بعد أن ذبحت في اليوم الأول، هل يجوز لي أن أذبح مرةً أخرى، أم أكتفي بالذبح في المرة الأولى؟وهل أذبح لزوجتي التي وكلتني برمي الجمرات لها؟ وإذا ذبحت لها الآن، هل يجوز ذلك أم وقت الحج؟ أرجو أن تفيدوني عن هذه القضايا. جزاكم الله خيرًا.كما أود إفادتكم بأنني سألت أحد الإخوة وهو إمام جامعٍ في أحد المساجد، وقد أفادني وقال لي: يمكنك أن تتصدق بثمن الهدي بشراء أحد التفاسير الدينية، وتتبرع بها بدلًا من أن تذبح، وفي نفس الوقت قال لي: نقرأ الفاتحة على الرسول ﷺ، وذلك باعتباري وعد مني بإرسال هذه التفاسير، بثمن الهدي، وأنا الآن محتار، وأخاف أن أكون قد أخلفت وعدي، وهل قراءة الفاتحة على الرسول ﷺ بهذه الصورة تعتبر وعدًا كما فعل هذا الشخص؟ وهل يجوز إرسال هذه التفاسير له باعتبارها بدلًا عن الهدي؟كما أفيدكم أيضًا بأنني لم أقم بعمل طواف الوداع، عند انتهائي من الحج، وذلك حسب ما سمعته من الإخوان الذين كانوا معي، قالوا لي: باعتبارك مقيم في المملكة؛ فلا يجب عليك طواف الوداع، سواء أديته أو لم تؤده، هل هذا صحيح، أم حجي ناقص؟ وهل يجوز أن أطوف مرةً ثانية بنية طواف الوداع؟ وهل يجوز لي ذبح هديٍ في هذه الحالة؛ لأني سمعت في إحدى الحلقات في برنامج: نور على الدرب، أحد الإخوة يسأل بأنه إذا لم يطف وسافر كانت الإجابة عليه أن يأتي إلى مكة ويطوف ويذبح هدي، إذا جامع زوجته، في طوال هذه المدة هل ينطبق علي ذلك أم يوجد حكم آخر على هذا الطواف؟وجهوني، جزاكم الله خيرًا.","title":"حكم من ترك رمي الجمرة الثالثة وطواف الوداع","answer":"الجواب: ليس عليك إلا فدية عن ترك الرمي، وعلى الزوجة أيضًا، فعليكما فديتان، عنك ذبيحة، وعنها ذبيحة، إذا كانت الذبيحة التي ذبحتها لم تقصد بها ذبيحة ترك الرمي، وإنما قصدت بها شيئًا آخر، فعليك ذبيحة واحدة عن نفسك، وذبيحة أخرى عن زوجتك، بسبب ترك الرمي، وهذه الذبيحة مثل الضحية، جذع ضأن، أو ثني معز، سليم من العيوب، يذبح في مكة للفقراء، والمساكين، سواء توليته بنفسك، أو وكلت ثقةً في مكة يقوم بذلك. وأما طواف الوداع فهو واجب، والذي قال: ليس عليك وداع وأنت في السعودية، هذا غلط، هذا جهل بحت، بل عليك ذبيحة أيضًا عن ترك الوداع؛ لأنه واجب، على الحاج إذا فرغ من حجه، وأراد السفر؛ أن يطوف للوداع؛ لقول النبي ﷺ: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت ولقول ابن عباس -رضي الله عنهما-: \"أمر الناس -يعني: أمرهم النبي- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فالمرأة الحائض والنفساء ليس عليهما وداع، وأما أنت عليك وداع، فلما تركته، فعليك ذبيحة تذبح في مكة للفقراء، مثل الضحية، جذع ضأن، أو ثني معز. وأما الذي قال لك: تخرج القيمة، فقد غلط، وهذا جهل منه، وهو يدل على عدم بصيرته، وأنه يقول على الله بغير علم، فالثمن لا يجزئ، سواء جعل في كتب للتفسير، أو غيره، إخراج القيمة أو الصدقة بالكتب، كل ذلك لا يقوم مقام الهدي. كذلك قراءة الفاتحة للنبي ﷺ بدعة، لا أساس لها، فنوصيك بالحذر من سؤال من لا يعرف بالعلم، والفضل، والبصيرة في الدين، لا تسأل إلا أهل العلم المعروفين بالورع، والعلم، والبصيرة في دين الله، والسمعة الحسنة؛ لأن كثيراً من الناس يقول على الله بغير علم، ويفتي على غير بصيرة، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13305/حكم-من-ترك-رمي-الجمرة-الثالثة-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64206.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":14812,"question":"المستمع: (خ .م . د) بعث برسالة وضمنها عددًا من الأسئلة، له سؤال طويل جدًا يقول فيه:في عام ألف وأربعمائة وسبعة، أديت فريضة الحج مع زوجتي، وهي كانت حامل، وأديت جميع المناسك الحمد لله بيسرٍ وسهولة، ولكن عند رجم الشيطان في اليوم الثاني، لم أتمكن من رمي الجمرة الثالثة، وكانت زوجتي قد وكلتني برمي جميع الجمرات لها؛ لأنها لم تتمكن من رميها، فإني حائر، وسألت عدة أشخاصٍ عن ذلك، بعضهم يقول لي: حجك صحيح، والبعض يقول لي: يتوجب عليك أن تذبح هدي؛ علمًا بأنني ذبحت هديًا واحدًا فقط لي، وهذا كان أول يوم العيد، قبل أن أرمي الجمرة الثانية؛ لأني قلت: يمكن أنني أنقصت شيئًا من المناسك، وحيث أنني لم أتمكن من رمي الجمرة الثالثة في اليوم الثاني، بعد أن ذبحت في اليوم الأول، هل يجوز لي أن أذبح مرةً أخرى، أم أكتفي بالذبح في المرة الأولى؟وهل أذبح لزوجتي التي وكلتني برمي الجمرات لها؟ وإذا ذبحت لها الآن، هل يجوز ذلك أم وقت الحج؟ أرجو أن تفيدوني عن هذه القضايا. جزاكم الله خيرًا.كما أود إفادتكم بأنني سألت أحد الإخوة وهو إمام جامعٍ في أحد المساجد، وقد أفادني وقال لي: يمكنك أن تتصدق بثمن الهدي بشراء أحد التفاسير الدينية، وتتبرع بها بدلًا من أن تذبح، وفي نفس الوقت قال لي: نقرأ الفاتحة على الرسول ﷺ، وذلك باعتباري وعد مني بإرسال هذه التفاسير، بثمن الهدي، وأنا الآن محتار، وأخاف أن أكون قد أخلفت وعدي، وهل قراءة الفاتحة على الرسول ﷺ بهذه الصورة تعتبر وعدًا كما فعل هذا الشخص؟ وهل يجوز إرسال هذه التفاسير له باعتبارها بدلًا عن الهدي؟كما أفيدكم أيضًا بأنني لم أقم بعمل طواف الوداع، عند انتهائي من الحج، وذلك حسب ما سمعته من الإخوان الذين كانوا معي، قالوا لي: باعتبارك مقيم في المملكة؛ فلا يجب عليك طواف الوداع، سواء أديته أو لم تؤده، هل هذا صحيح، أم حجي ناقص؟ وهل يجوز أن أطوف مرةً ثانية بنية طواف الوداع؟ وهل يجوز لي ذبح هديٍ في هذه الحالة؛ لأني سمعت في إحدى الحلقات في برنامج: نور على الدرب، أحد الإخوة يسأل بأنه إذا لم يطف وسافر كانت الإجابة عليه أن يأتي إلى مكة ويطوف ويذبح هدي، إذا جامع زوجته، في طوال هذه المدة هل ينطبق علي ذلك أم يوجد حكم آخر على هذا الطواف؟وجهوني، جزاكم الله خيرًا.","title":"حكم من ترك رمي الجمرة الثالثة وطواف الوداع","answer":"الجواب: ليس عليك إلا فدية عن ترك الرمي، وعلى الزوجة أيضًا، فعليكما فديتان، عنك ذبيحة، وعنها ذبيحة، إذا كانت الذبيحة التي ذبحتها لم تقصد بها ذبيحة ترك الرمي، وإنما قصدت بها شيئًا آخر، فعليك ذبيحة واحدة عن نفسك، وذبيحة أخرى عن زوجتك، بسبب ترك الرمي، وهذه الذبيحة مثل الضحية، جذع ضأن، أو ثني معز، سليم من العيوب، يذبح في مكة للفقراء، والمساكين، سواء توليته بنفسك، أو وكلت ثقةً في مكة يقوم بذلك. وأما طواف الوداع فهو واجب، والذي قال: ليس عليك وداع وأنت في السعودية، هذا غلط، هذا جهل بحت، بل عليك ذبيحة أيضًا عن ترك الوداع؛ لأنه واجب، على الحاج إذا فرغ من حجه، وأراد السفر؛ أن يطوف للوداع؛ لقول النبي ﷺ: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت ولقول ابن عباس -رضي الله عنهما-: \"أمر الناس -يعني: أمرهم النبي- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فالمرأة الحائض والنفساء ليس عليهما وداع، وأما أنت عليك وداع، فلما تركته، فعليك ذبيحة تذبح في مكة للفقراء، مثل الضحية، جذع ضأن، أو ثني معز. وأما الذي قال لك: تخرج القيمة، فقد غلط، وهذا جهل منه، وهو يدل على عدم بصيرته، وأنه يقول على الله بغير علم، فالثمن لا يجزئ، سواء جعل في كتب للتفسير، أو غيره، إخراج القيمة أو الصدقة بالكتب، كل ذلك لا يقوم مقام الهدي. كذلك قراءة الفاتحة للنبي ﷺ بدعة، لا أساس لها، فنوصيك بالحذر من سؤال من لا يعرف بالعلم، والفضل، والبصيرة في الدين، لا تسأل إلا أهل العلم المعروفين بالورع، والعلم، والبصيرة في دين الله، والسمعة الحسنة؛ لأن كثيراً من الناس يقول على الله بغير علم، ويفتي على غير بصيرة، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13305/حكم-من-ترك-رمي-الجمرة-الثالثة-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64206.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":14970,"question":"أيضًا يقول: ما حكم من عكس العمرة، فقدم السعي على الطواف وتحلل؟","title":"ما حكم من قدم السعي على الطواف؟","answer":"الجواب: الصواب أنه لا حرج عليه، ولا حرج في تقديم السعي على الطواف، السنة أن يكون بعد الطواف، كما طاف النبي ﷺ وسعى، هذا السنة، لكن من جهل أو نسي؛ صحت عمرته وصح حجه، فإذا سعى قبل الطواف في العمرة، أو سعى قبل الطواف في الحج؛ أجزأه ذلك لأمرين:\nأحدهما: قول النبي ﷺ لما سئل عن أعمال الحج يوم العيد: افعل ولا حرج، افعل ولا حرج سئل عن التقديم والتأخير فكان يقول: افعل ولا حرج قال الراوي: فما سئل يؤمئذٍ عن شيء قدم ولا أخر إلا قال: افعل ولا حرج وهذا يعم الطواف والسعي، وإذا جاز في الحج جاز في العمرة؛ لأن أحكامهما سواء، والحج أعظم. الأمر الثاني: أنه ثبت عنه -عليه الصلاة والسلام- بإسناد صحيح عند أبي داود أن رجلًا سأل النبي ﷺ فقال: «يا رسول الله، سعيت قبل أن أطوف، قال: افعل ولا حرج لما سأله عن السعي قال: لا حرج يعني: السعي قبل الطواف، قال: لا حرج وهذا نص صحيح صريح يؤيد العموم السابق، وهذا قول جماعة من أهل العلم، والأكثر على أنه لا بد من تقديم الطواف على السعي، ولكن الصحيح هو جواز تقديم السعي وإن كان خلاف قول الأكثر؛ لأن المعول هو الدليل، المعول عليه هو الدليل، والله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ..[النساء:59]الآية، ويقول : وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ[الشورى:10]الآية، نعم. المقدم: شكرًا لفضيلة الشيخ عبدالعزيز .","link":"https://binbaz.org.sa/fatwas/13468/ما-حكم-من-قدم-السعي-على-الطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64907.mp3","categories":["الطواف بالبيت","السعي"]},{"id":16038,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أرجو أن توضحوا لنا توضيحًا كاملًا، وشاملًا: كيف تبدأ عملية السعي بين الصفا والمروة، من أين نبدأ، ومتى ننتهي؟ هل الشوط الواحد يكون بداية من الصفا والوصول للمروة هذا واحد؟ أم البداية من الصفا والرجوع مرةً أخرى للصفا يعد واحدة؟ أفيدونا أفادكم الله.","title":"كيفية السعي بين الصفا والمروة","answer":"الجواب: السعي يبدأ من الصفا، ويختم من المروة، والسعي شوط واحد من الصفاء للمروة هذا واحد، ومن المروة إلى الصفا شوط ثاني، وهكذا، فالمقصود أنها سبعة أشواط، يبدأ الساعي من الصفا، ويختم بالمروة، فإذا بدأ من الصفا، ووصل المروة هذا واحد، وإذا رجع من المروة إلى الصفا هذا اثنين، وإذا رجع من الصفا للمروة هذا ثلاثة .. وهكذا حتى يكمل السبعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14681/كيفية-السعي-بين-الصفا-والمروة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74810.mp3","categories":["الطواف بالبيت","السعي"]},{"id":16947,"question":"يقول: بعض الناس يلزم المرأة بالسعي كالرجال، فهل هذا صحيح؟ أم أن المرأة لها أحكام في السعي خاصة؟","title":"كيفية سعي المرأة","answer":"الجواب: نعم، المرأة لا يشرع لها الهرولة في الوادي، ولا الرمل في الطواف؛ لأنها عورة، فتمشي في الطواف والسعي، هكذا ذكر أهل العلم.","link":"https://binbaz.org.sa/fatwas/15751/كيفية-سعي-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82813.mp3","categories":["قضايا المرأة","السعي"]},{"id":16961,"question":"حدثونا عن السعي بين الصفا والمروة؟ هل هو واجب على كل حاج؟ أم على صنف دون صنف؟","title":"السعي ركن من أركان الحج والعمرة","answer":"الجواب: السعي واجب على جميع الحجاج، بين الصفا والمروة، واجب، ركن من أركان الحج، والعمرة، مع الطواف، في حق المتمتع، والقارن، والمفرد، لكن في حق المتمتع يلزمه سعي ثان للحج، والأول يكون للعمرة، أما القارن، والمفرد فليس عليه إلا سعي واحد، إن سعاه قبل عرفة؛ أجزأه، وإلا سعاه مع طواف الإفاضة، بعد عرفة، إذا كان أفقيًا جاء من الخارج. أما إذا كان من أهل مكة فإن سعيه وطوافه يكون بعد الحج، يؤخر إلى بعد الحج، لا يقدم، أما من جاء من خارج، من جدة، من الرياض، من أبعد منهما، هذا إذا دخل يطوف للقدوم، ويسعى، إذا كان مفردًا، أو قارنًا، ثم عليه طواف للإفاضة بعد الحج، ويجزيه السعي إن سعى قبل الحج، ويلزمه طواف الإفاضة فقط، مع طواف الوداع، أما المتمتع السعي الأول يكون لعمرته، وعليه أن يسعى سعيًا ثانيًا لحجه، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15743/السعي-ركن-من-اركان-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82808.mp3","categories":["الطواف بالبيت","السعي"]},{"id":17115,"question":"من أسئلة هذه السائلة: (س. ن) من جدة تقول: سماحة الشيخ! ما حكم حمل الطفل أثناء الصلاة، أو الطواف وهو لابس حفاظة، وفيها نجاسة، ولكنها لم تتعد الملابس الخارجية، وجزاكم الله خيرًا.","title":"حكم حمل الطفل أثناء الصلاة والطواف","answer":"الجواب: النبي ﷺ صلى بـأمامة بنت زينب، وهو يصلي بالناس -عليه الصلاة والسلام- فإذا حمل الطفل في الصلاة عند الحاجة، أو في الطواف لا حرج، فالنبي ﷺ صلى بـأمامة بنت زينب وهي صغيرة، والطفل قد لا يسلم من خروج شيء منه، فإذا لم يكن هناك شيء ظاهر، ومحفظ فلا بأس، الحمد لله. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15922/حكم-حمل-الطفل-اثناء-الصلاة-والطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58912.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":17377,"question":"تقول السائلة: هل يجوز الفصل بين طواف العمرة، وإكمال واجباتها، كالخروج إلى الفندق مثلًا -وهو بجوار الحرم- للضرورة كالنوم والأكل؟","title":"حكم الفصل بين طواف العمرة والسعي","answer":"الجواب: لا بأس، لا بأس بتأخير السعي، مثلًا طاف اليوم، وسعى غدًا، أو طاف في أول النهار، وسعى في آخر النهار، لا حرج في ذلك. المقدم: جزاكم الله عنا، وعن المسلمين خير الجزاء، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16227/حكم-الفصل-بين-طواف-العمرة-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59402.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":18780,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من جدة، وباعثها مستمع رمز إلى اسمه بالحروف: (أ. م. أ. ط) أخونا يقول: أحرمت بالحج مفردًا من مكان إقامتي في جدة، ليلة الثامن من ذي الحجة، وطفت طواف القدوم قبل يوم التروية، ثم سعيت سعي الحج بعد صلاة فجر يوم التروية، فهل الترتيب الزمني الذي أديت فيه المناسك المذكورة صحيح؟جزاكم الله خيرًا.","title":"حكم الفصل بين طواف القدوم والسعي في الحج للمفرد","answer":"الجواب: لا حرج في ذلك صحيح، والحمد لله، لكن لو سعيت مع الطواف مبادرة فهو أفضل، ولكن تأخيره كونك طفت في ليلة الثامن، أو في اليوم التاسع، ثم طفت في الليلة الثامنة أو في يوم الثامن، ثم سعيت في صباح يوم التاسع أو في يوم التروية لا بأس. المقصود: الفصل بين السعي وبين الطواف لا يضر، لكن كون السعي يلي الطواف هذا هو الأفضل، فإذا طاف الإنسان في اليوم الثامن، أو في السابع، ثم سعى بعد ذلك في اليوم الذي بعده، أو في الليلة، فلا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17944/حكم-الفصل-بين-طواف-القدوم-والسعي-في-الحج-للمفرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73602.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":18930,"question":"سائل للبرنامج يقول في سؤاله هذا يا فضيلة الشيخ: سماحة الشيخ، كيف يكون التكبير على الصفا والمروة؟","title":"كيفية التكبير على الصفا والمروة","answer":"الجواب: كان النبي ﷺ إذا صعد الصفا كبر عليها، وذكر الله ثلاثًا، ودعا ثلاثًا، وكرر، يقول: لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، يحيي ويميت وهو على كل شيء قدير، لا إله إلا الله وحده أنجز وعده، ونصر عبده، وهزم الأحزاب وحده، ويكرر ذلك مع التكبير ثلاث مرات، مع الدعاء على الصفا والمروة، هذا هو الأفضل. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18067/كيفية-التكبير-على-الصفا-والمروة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88205.mp3","categories":["الأدعية والأذكار","الطواف بالبيت","السعي"]},{"id":19710,"question":"السعي يُشترط له طهارة؟","title":"هل تشترط الطهارة للسعي بين الصفا والمروة؟","answer":"لا، الطواف فقط.","link":"https://binbaz.org.sa/fatwas/27028/هل-تشترط-الطهارة-للسعي-بين-الصفا-والمروة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%87%D9%84%20%D8%AA%D8%B4%D8%AA%D8%B1%D8%B7%20%D8%A7%D9%84%D8%B7%D9%87%D8%A7%D8%B1%D8%A9%20%D9%84%D9%84%D8%B3%D8%B9%D9%8A%20%D8%A8%D9%8A%D9%86%20%D8%A7%D9%84%D8%B5%D9%81%D8%A7%20%D9%88%D8%A7%D9%84%D9%85%D8%B1%D9%88%D8%A9%D8%9F.mp3","categories":["الطواف بالبيت","السعي"]}]
